python3 - <<'PY'
p='classic/rust/crates/podcast/src/coverage.rs';s=open(p).read().replace('pub struct CameraClockOptions {\n    pub sources: Vec<CameraSource>,','pub struct CameraClockOptions {\n    pub sources: Vec<CameraSource>,\n    /// Advanced mode trims camera-only lead/tail to external microphone coverage.\n    #[serde(default)]\n    pub microphones: Vec<CameraSource>,');s=s.replace('    Some(CameraClock {\n        reference_id: longest.id.clone(),\n        origin: longest.start,\n        duration: longest.duration,\n    })','''    let (origin,duration)=if o.microphones.is_empty() {
        (longest.start,longest.duration)
    } else {
        if o.microphones.len()>4 || o.microphones.iter().any(|s|s.id.is_empty() || !s.start.is_finite() || !s.duration.is_finite() || s.duration<=0.0 || s.duration>36000.0 || s.start.abs()>36000.0) {return None;}
        let start=o.microphones.iter().map(|s|s.start).min_by(f64::total_cmp).unwrap().max(longest.start);
        let end=o.microphones.iter().map(|s|s.start+s.duration).max_by(f64::total_cmp).unwrap().min(longest.start+longest.duration);
        if end<=start {return None;}
        (start,end-start)
    };
    Some(CameraClock {reference_id:longest.id.clone(),origin,duration})''');# rust struct literal currenttests need optionalfield
# print instances before writing separately
open(p,'w').write(s)
