        microphones:advanced?.microphones.map(m=>({id:m.id,duration:m.duration,start:offsets.get(m.id)!,bindingRevision:0})),
\t\tsources: baseVideos.map''';s=s.replace(needle,repl,1);open(p,'w').write(s)
